import React from 'react';

const About = () => {
    const sectionStyle = {
        padding: '2rem',
        backgroundColor: '#f9f9f9',
        borderRadius: '8px',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
        maxWidth: '800px',
        margin: '2rem auto',
        fontFamily: 'Arial, sans-serif',
        lineHeight: '1.6',
    };

    const headingStyle = {
        fontSize: '2rem',
        color: '#333',
        marginBottom: '1rem',
        textAlign: 'center',
    };

    const paragraphStyle = {
        fontSize: '1.2rem',
        color: '#555',
        textAlign: 'center',
    };

    return (
        <section style={sectionStyle}>
            <h1 style={headingStyle}>About Me</h1>
            <p style={paragraphStyle}>
                Hi, I am <strong>Duclayan, Krizstian Marco G.</strong>, a <strong>BSIT Student</strong>. I am passionate about 
                <strong> Hardware and Software troubleshooting</strong>. I enjoy learning new things and troubleshooting and repairing computers.
                I am currently studying at <strong>University of Cabuyao</strong>, where I am gaining knowledge and skills about computers and technology.
                I am always eager to learn and grow in my field. I believe that technology has the power to change the world, and I want to be a part of that change.
                In my free time, I enjoy exploring new technologies, working on personal projects, and contributing to open-source communities.
                I am excited to connect with like-minded individuals and collaborate on projects that make a difference.
                If you would like to know more about me or my work, feel free to reach out!
                I am always open to new opportunities and collaborations. Let's connect and explore the possibilities together!
                <br />
            </p>
        </section>
    );
};

export default About;
